svg.script:
(function () {
 const n = 4;
 const bits = 2;
 const labels = ['a', 'b', 'c', 'd'];
 const ys = [28, 60, 92, 124];
 let selection = 0;
 const el = id => document.getElementById(id);
 function render() {
  for (let i = 0; i < n; i++) {
   let active = i === selection;
   el('wire-' + i).setAttribute('class', active ? 'wire active' : 'wire');
   el('wire-' + i).setAttribute('marker-end', active ? 'url(#activeArrow)' : 'url(#arrow)');
   el('name-' + i).setAttribute('class', active ? 'name active' : 'name');
   el('value-' + i).textContent = active ? 'in' : '0';
   el('value-' + i).setAttribute('fill', active ? '#b72f17' : '#596579');
  }
  el('selected-route').setAttribute('d', 'M230 76.0 L365 ' + ys[selection]);
  el('selection-label').textContent = 'sel = ' + selection.toString(2).padStart(bits, '0') + ' → ' + labels[selection];
  for (let bit=0;bit<bits;bit++) {
   let on = !!(selection & (1 << bit));
   el('state-'+bit).textContent = on ? '1' : '0';
   el('switch-'+bit).setAttribute('class',on ? 'switch on' : 'switch');
   el('switch-'+bit).setAttribute('aria-pressed', on ? 'true' : 'false');
  }
 }
 for (let bit=0;bit<bits;bit++) {
  const sw=el('switch-'+bit);
  const toggle=()=>{selection ^= (1<<bit);render();};
  sw.addEventListener('click',toggle);
  sw.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();toggle();}});
 }
 render();
})();
